# Let me debug and properly count components
from collections import deque, Counter

def count_components_properly(grid):
    """Properly count connected components for each color"""
    rows, cols = len(grid), len(grid[0])
    global_visited = set()  # Track all visited across colors
    components_by_color = {c: [] for c in [0,1,3,7,9]}  # Skip 5

    for r in range(rows):
        for c in range(cols):
            if (r, c) not in global_visited and grid[r][c] != 5:
                color = grid[r][c]

                # BFS to find component
                queue = deque([(r, c)])
                local_visited = {(r, c)}
                size = 0

                while queue:
                    curr_r, curr_c = queue.popleft()
                    global_visited.add((curr_r, curr_c))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in global_visited and grid[nr][nc] == color:
                                local_visited.add((nr, nc))
                                queue.append((nr, nc))

                components_by_color[color].append(size)

    return components_by_color

